    __stickytape_write_module('sections/hostname.py', b'"""Hostname and self-resolution. Nothing changes unless SYSTEM_HOSTNAME/DOMAIN/FQDN is set."""\n\nfrom actions import Cmd, EnsureLine, out\nfrom config import Config\n\n\ndef actions(c: Config):\n    if not c.static_hostname:\n        return []\n    return [\n        Cmd(\n            name=f"set hostname {c.static_hostname}",\n            argv=["hostnamectl", "set-hostname", c.static_hostname],\n            done=lambda: out("hostnamectl", "--static") == c.static_hostname,\n        ),\n        # Self-resolution without DNS: one marked line, rewritten on every run\n        EnsureLine(\n            path=c.hosts_file,\n            line=c.hosts_line,\n            marker=c.hosts_marker,\n        ),\n    ]\n')
    __stickytape_write_module('sections/identity.py', b'"""Accounts and local access policy: MOTD, sudo, passwords, faillock, admin user, su restriction, admin SSH key."""\n\nimport os\n\nimport texts\nfrom actions import Cmd, EnsureDir, Func, Systemctl, WriteFile, ok, out, sh\nfrom config import MIDFIX, Config\n\nUNITS = "/etc/systemd/system"\n\n\ndef password(user: str, hash_: str) -> Cmd:\n    def current() -> bool:\n        fields = out("getent", "shadow", user).split(":")\n        return len(fields) > 1 and fields[1] == hash_\n    return Cmd(\n        name=f"password for {user}",\n        argv=["chpasswd", "-e"],\n        input=f"{user}:{hash_}\\n",\n        done=current,\n    )\n\n\ndef _su_ok(c: Config) -> bool:\n    import grp\n    st = os.stat(c.su_bin)\n    return (st.st_mode & 0o7777) == c.su_mode and grp.getgrgid(st.st_gid).gr_name == c.admin_group\n\n\ndef _su_restrict(c: Config) -> None:\n    sh("chgrp", c.admin_group, c.su_bin)\n    os.chmod(c.su_bin, c.su_mode)\n\n\ndef _authselect_ok(c: Config) -> bool:\n    current = out("authselect", "current", "-r").split()\n    return bool(current) and current[0] == c.authselect_profile and set(c.authselect_features) <= set(current[1:])\n\n\ndef actions(c: Config):\n    return [\n        WriteFile(\n            path="/etc/motd",\n            text=texts.motd(c),\n        ),\n        EnsureDir(\n            path=c.sudoers_dir,\n        ),\n        WriteFile(\n            path=c.sudo_conf,\n            text=texts.sudo_conf(c),\n            mode=0o440,\n            validator=["visudo", "-c", "-f"],\n        ),\n        password("root", c.root_password_hash),\n        # Disallow empty passwords via authselect\n        Cmd(\n            name="authselect profile",\n            argv=["authselect", "select", c.authselect_profile, *c.authselect_features, "--force"],\n            done=lambda: _authselect_ok(c),\n        ),\n        # Limit password guessing (stock file is comments only, so we own it whole)\n        WriteFile(\n            path="/etc/security/faillock.conf",\n            text=texts.FAILLOCK_CONF,\n        ),\n        # Session timeout (15 minutes idle); a default, not a hard control\n        WriteFile(\n            path=f"/etc/profile.d/{MIDFIX}-timeout.sh",\n            text=texts.TIMEOUT_CONF,\n        ),\n        # Admin user\n        Cmd(\n            name=f"create {c.admin_user}",\n            argv=["useradd", "-m", "-s", c.admin_shell, c.admin_user],\n            done=lambda: ok("id", "-u", c.admin_user),\n        ),\n        password(c.admin_user, c.admin_password_hash),\n        Cmd(\n            name=f"{c.admin_user} in {c.admin_group}",\n            argv=["usermod", "-aG", c.admin_group, c.admin_user],\n            done=lambda: c.admin_group in out("id", "-nG", c.admin_user).split(),\n        ),\n        # Restrict su to the admin group (re-applied by the su-guard units after package updates)\n        Func(\n            name=f"restrict {c.su_bin}",\n            run=lambda: _su_restrict(c),\n            pre=lambda: _su_ok(c),\n            post=lambda: _su_ok(c),\n        ),\n        WriteFile(\n            path=c.su_guard_bin,\n            text=texts.su_guard_bin(c),\n            mode=0o755,\n            relabel=True,\n        ),\n        WriteFile(\n            path=f"{UNITS}/{c.su_guard_service}",\n            text=texts.su_guard_service(c),\n        ),\n        WriteFile(\n            path=f"{UNITS}/{c.su_guard_path}",\n            text=texts.su_guard_path(c),\n        ),\n        WriteFile(\n            path=f"{UNITS}/{c.su_guard_timer}",\n            text=texts.su_guard_timer(c),\n        ),\n        Systemctl(\n            verb="daemon_reload",\n        ),\n        Systemctl(\n            verb="enable_now",\n            units=[c.su_guard_path, c.su_guard_timer],\n        ),\n        # Admin sudo access (password required)\n        WriteFile(\n            path=c.admin_sudoers_conf,\n            text=texts.admin_sudoers(c),\n            mode=0o440,\n            validator=["visudo", "-c", "-f"],\n        ),\n        # Authorize the master public key for the admin user\n        EnsureDir(\n            path=c.admin_ssh_dir,\n            mode=0o700,\n            owner=c.admin_user,\n            group=c.admin_user,\n            relabel=True,\n        ),\n        WriteFile(\n            path=c.admin_authorized_keys,\n            text=c.admin_pubkey,\n            mode=0o600,\n            owner=c.admin_user,\n            group=c.admin_user,\n            relabel=True,\n        ),\n    ]\n')
    __stickytape_write_module('sections/kernel.py', b'"""Kernel hardening (sysctl) and auditing."""\n\nimport texts\nfrom actions import Cmd, Systemctl, WriteFile\nfrom config import MIDFIX, Config\n\n\ndef actions(c: Config):\n    return [\n        WriteFile(\n            path=f"/etc/sysctl.d/99-{MIDFIX}-hardening.conf",\n            text=texts.SYSCTL_HARDENING,\n        ),\n        Cmd(\n            name="apply sysctl",\n            argv=["sysctl", "--system"],\n        ),\n        WriteFile(\n            path=f"/etc/audit/rules.d/99-{MIDFIX}.rules",\n            text=texts.AUDIT_RULES,\n            mode=0o640,\n        ),\n        Systemctl(\n            verb="enable_now",\n            units=["auditd"],\n        ),\n        # Rules apply on next boot if they cannot be loaded now\n        Cmd(\n            name="load audit rules",\n            argv=["augenrules", "--load"],\n            continue_on_error=True,\n        ),\n    ]\n')
    __stickytape_write_module('sections/logs.py', b'"""rsyslog routing and logrotate for the logs this script creates."""\n\nimport texts\nfrom actions import Systemctl, WriteFile\nfrom config import MIDFIX, Config\n\n\ndef actions(c: Config):\n    return [\n        WriteFile(\n            path=f"/etc/rsyslog.d/99-{MIDFIX}-nftables.conf",\n            text=texts.rsyslog_nft(c),\n        ),\n        WriteFile(\n            path=f"/etc/rsyslog.d/99-{MIDFIX}-popola-switch.conf",\n            text=texts.rsyslog_popola(c),\n        ),\n        Systemctl(\n            verb="restart",\n            units=["rsyslog"],\n        ),\n        # Sudo log (30 days)\n        WriteFile(\n            path=f"/etc/logrotate.d/99-{MIDFIX}-sudo",\n            text=texts.logrotate(c.sudo_log, "daily", 30),\n        ),\n        # nftables log (postrotate reloads rsyslog to reopen the file)\n        WriteFile(\n            path=f"/etc/logrotate.d/99-{MIDFIX}-nftables",\n            text=texts.logrotate(c.nft_log, "daily", 7, compress=False, reload_rsyslog=True),\n        ),\n        # Service-user switch log (a year)\n        WriteFile(\n            path=f"/etc/logrotate.d/99-{MIDFIX}-popola-switch",\n            text=texts.logrotate(c.popola_log, "weekly", 52, reload_rsyslog=True),\n        ),\n    ]\n')
    __stickytape_write_module('sections/network.py', b'"""Static IPv4 as a NetworkManager keyfile. Written before AIDE (so the baseline includes it) but\nactivated as the very last step of the whole script: the address change drops an SSH session on the\nold address, so nothing may run after it."""\n\nimport texts\nfrom actions import Cmd, WriteFile, out\nfrom config import MIDFIX, Config\n\n\ndef write(c: Config):\n    if not c.static_ip:\n        return []\n    return [\n        WriteFile(\n            path=c.nm_conf,\n            text=texts.nm_keyfile(c),\n            mode=0o600,\n            relabel=True,\n        ),\n        Cmd(\n            name="reload NetworkManager",\n            argv=["nmcli", "connection", "reload"],\n        ),\n    ]\n\n\ndef _active(c: Config) -> bool:\n    return c.nm_connection in out("nmcli", "-t", "-f", "NAME", "connection", "show", "--active").splitlines()\n\n\ndef activate(c: Config):\n    """Delayed via a transient systemd unit so the script exits cleanly first."""\n    if not c.static_ip:\n        return []\n    return [\n        Cmd(\n            name=f"activate {c.nm_connection} in {c.static_apply_delay} (an SSH session on the old address will drop)",\n            argv=[\n                "systemd-run",\n                f"--unit={MIDFIX}-static-ip-apply",\n                f"--on-active={c.static_apply_delay}",\n                "nmcli", "connection", "up", c.nm_connection,\n            ],\n            done=lambda: _active(c),\n        ),\n    ]\n')
    __stickytape_write_module('sections/packages.py', b'"""Security updates, repositories and base tooling, then time sync and job schedulers."""\n\nfrom actions import Cmd, DnfInstall, Systemctl\nfrom config import Config\n\n\ndef actions(c: Config):\n    return [\n        # Security updates only (same policy as dnf-automatic), then base tooling\n        Cmd(\n            name="dnf upgrade --security",\n            argv=["dnf", "upgrade", "--security", "-y"],\n        ),\n        # Both come from the stock repos, so one transaction. Everything after needs EPEL\'s metadata,\n        # which only exists once epel-release is installed, so c.packages must be a separate transaction.\n        DnfInstall(\n            packages=["dnf-plugins-core", "epel-release"],\n        ),\n        # EPEL packages can depend on CodeReady Builder (crb); config-manager comes from dnf-plugins-core\n        Cmd(\n            name="enable crb repo",\n            argv=["dnf", "config-manager", "--set-enabled", "crb"],\n        ),\n        DnfInstall(\n            packages=c.packages,\n        ),\n        Systemctl(\n            verb="enable_now",\n            units=["chronyd"],\n        ),\n        Systemctl(\n            verb="enable_now",\n            units=["crond"],\n        ),\n        Systemctl(\n            verb="enable_now",\n            units=["atd"],\n        ),\n    ]\n')
    __stickytape_write_module('sections/preflight.py', b'"""Every input check runs here, before the first change to the system, so a bad value aborts a clean run."""\n\nimport json\nimport os\nimport re\nimport subprocess\nimport tempfile\nimport urllib.request\nfrom dataclasses import replace\n\nfrom actions import sh\nfrom config import Config\n\nCIDR_RE = re.compile(r"^([0-9]{1,3}\\.){3}[0-9]{1,3}/[0-9]{1,2}$")\n\n\nclass PreflightError(RuntimeError):\n    pass\n\n\ndef _default_route(*extra: str) -> dict:\n    routes = json.loads(sh("ip", "-j", "-4", "route", "show", "default", *extra).stdout or "[]")\n    return routes[0] if routes else {}\n\n\ndef resolve_network(c: Config) -> Config:\n    """Validate STATIC_IP and fill in the interface and gateway of the current default route when unset."""\n    if not c.static_ip:\n        return c\n    if not CIDR_RE.match(c.static_ip):\n        raise PreflightError(f"STATIC_IP must be IPv4 CIDR (e.g. 192.168.1.50/24), got: {c.static_ip}")\n    iface = c.static_iface or _default_route().get("dev", "")\n    if not iface:\n        raise PreflightError("Could not detect the default-route interface, set STATIC_IFACE")\n    gateway = c.static_gateway or _default_route("dev", iface).get("gateway", "")\n    if not gateway:\n        raise PreflightError(f"Could not detect the default gateway on {iface}, set STATIC_GATEWAY")\n    return replace(c, static_iface=iface, static_gateway=gateway)\n\n\ndef check_pubkey(key_text: str) -> None:\n    """sshd accepts only ed25519 and password auth is off, so any other key type would lock the admin out."""\n    with tempfile.NamedTemporaryFile("w", delete=False) as f:\n        f.write(key_text)\n    try:\n        result = subprocess.run(["ssh-keygen", "-l", "-f", f.name], text=True, capture_output=True)\n    finally:\n        os.unlink(f.name)\n    info = result.stdout.strip()\n    if result.returncode != 0 or not info or any(not line.endswith("(ED25519)") for line in info.splitlines()):\n        raise PreflightError(f"Admin public key must be ssh-ed25519 only, got:\\n{info or result.stderr.strip()}")\n\n\ndef run(c: Config) -> Config:\n    """Return the config with network values resolved and the validated admin public key loaded."""\n    c = resolve_network(c)\n    with urllib.request.urlopen(c.admin_pubkey_url, timeout=30) as response:  # downloaded now, installed later\n        key_text = response.read().decode("utf-8")\n    check_pubkey(key_text)\n    return replace(c, admin_pubkey=key_text)\n')
    __stickytape_write_module('sections/prune.py', b'"""Remove every other regular login user. Runs last among the account steps.\r\n\r\nOnly regular accounts (UID_MIN..UID_MAX from login.defs) are candidates. Preview: PRUNE_DRY_RUN=1.\r\n"""\r\n\r\nimport logging\r\nimport re\r\nimport time\r\nfrom pathlib import Path\r\n\r\nfrom actions import Func, ok, sh\r\nfrom config import Config\r\n\r\nlog = logging.getLogger(__name__)\r\n\r\n\r\ndef _uid_range() -> tuple[int, int]:\r\n    values = {}\r\n    for line in Path("/etc/login.defs").read_text().splitlines():\r\n        parts = line.split()\r\n        if len(parts) >= 2 and parts[0] in ("UID_MIN", "UID_MAX"):\r\n            values[parts[0]] = int(parts[1])\r\n    return values.get("UID_MIN", 1000), values.get("UID_MAX", 60000)\r\n\r\n\r\ndef stale_users(c: Config) -> list[str]:\r\n    import pwd\r\n    low, high = _uid_range()\r\n    keep = {c.admin_user, c.service_user, c.sudo_user}\r\n    return [u.pw_name for u in pwd.getpwall() if low <= u.pw_uid <= high and u.pw_name not in keep]\r\n\r\n\r\ndef _remove(c: Config, user: str) -> None:\r\n    log.info("Removing user %s", user)\r\n    sh("usermod", "-L", "-s", "/sbin/nologin", user)\r\n    sh("pkill", "-KILL", "-u", user, check=False)\r\n    for _ in range(50):  # userdel refuses while processes remain: wait up to ~10s\r\n        if not ok("pgrep", "-u", user):\r\n            break\r\n        time.sleep(0.2)\r\n    # Drop sudoers grants that name this user (e.g. cloud-init\'s 90-cloud-init-users)\r\n    pattern = re.compile(rf"^{re.escape(user)}\\s", re.MULTILINE)\r\n    for f in Path(c.sudoers_dir).iterdir():\r\n        if f.is_file() and pattern.search(f.read_text(errors="replace")):\r\n            f.unlink()\r\n    if sh("userdel", "-r", user, check=False).returncode != 0:\r\n        log.warning("could not fully remove %s", user)\r\n\r\n\r\ndef _run(c: Config) -> None:\r\n    for user in stale_users(c):\r\n        if c.prune_dry_run:\r\n            log.info("DRY RUN: would remove user %s", user)\r\n        else:\r\n            _remove(c, user)\r\n\r\n\r\ndef actions(c: Config):\r\n    return [\r\n        Func(\r\n            name="remove other login users",\r\n            run=lambda: _run(c),\r\n            pre=lambda: not stale_users(c),\r\n            post=lambda: c.prune_dry_run or not stale_users(c),\r\n        ),\r\n    ]\r\n')
    __stickytape_write_module('sections/service_user.py', b'"""Service user: no direct login (nologin shell, locked password), reachable only via sudo from the admin."""\n\nimport texts\nfrom actions import Cmd, WriteFile, ok, out\nfrom config import Config\n\n\ndef _locked(user: str) -> bool:\n    fields = out("passwd", "-S", user).split()\n    return len(fields) > 1 and fields[1] in ("L", "LK")\n\n\ndef actions(c: Config):\n    return [\n        # No home directory (-M, /nonexistent)\n        Cmd(\n            name=f"create {c.service_user}",\n            argv=["useradd", "-M", "-d", "/nonexistent", "-s", c.service_shell, "-c", c.service_comment, c.service_user],\n            done=lambda: ok("id", "-u", c.service_user),\n        ),\n        Cmd(\n            name=f"lock {c.service_user}",\n            argv=["passwd", "-l", c.service_user],\n            done=lambda: _locked(c.service_user),\n        ),\n        # Runs bash directly: sudo -i would use the nologin shell and su would ask for the locked password\n        WriteFile(\n            path=c.service_sudoers_conf,\n            text=texts.service_sudoers(c),\n            mode=0o440,\n            validator=["visudo", "-c", "-f"],\n        ),\n    ]\n')
